// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address caller, address recipient, uint256 amount) public {
        vm.assume(caller != address(this));
        vm.assume(recipient != address(0));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 balBefore = address(c).balance;
        vm.prank(caller);
        try c.withdrawAll(recipient) {
            assertTrue(balBefore == 0);
        } catch {
            assertTrue(address(c).balance == balBefore);
        }
    }
}
